#!/usr/bin/env python3
"""生成归一化候选的样例表（tests/fixtures/dupe_normalize.xlsx）。

用途：验证重复检测漏斗第二级（归一化候选）——
「同一条业务记录被填了两遍，只是写法不一样」：

- 指标名称别名（院感前缀 / 官方写法）；
- 全角与半角（ＣＴ／ＭＲＩ vs CT/MRI）；
- 指标名称为空、单位别名未覆盖（落「未归一」并计数）。

两张工作表 = 两张来源表，验证跨表场景。

数据只到**指标级监管数据**，不含任何患者可识别明细；业务主键统一带
`BK-NORM-` 前缀以便与真实数据区分。

可重跑：每次生成的文件内容一致（openpyxl 写入的内容与时间戳无关）。
"""

from pathlib import Path

from openpyxl import Workbook

HERE = Path(__file__).resolve().parent
OUT = HERE / "dupe_normalize.xlsx"

HEADERS = [
    "指标编号",
    "指标名称",
    "科室代码",
    "科室名称",
    "报告期",
    "分子",
    "分母",
    "填报值",
    "计量单位",
    "业务主键",
    "备注",
]

# 科室一表：别名写法 + 同表内重复填报 + 半角写法 + 两条未归一
SHEET_ONE = [
    [
        "MER-ME-03",
        "院感细菌培养检查记录符合率",
        "0301",
        "医技部",
        "2026-Q3",
        "995",
        "1000",
        "99.5",
        "%",
        "BK-NORM-01",
        "指标名称别名写法（院感前缀）",
    ],
    [
        "MER-ME-03",
        "细菌培养检查记录符合率",
        "0301",
        "医技部",
        "2026-Q3",
        "995",
        "1000",
        "99.5",
        "%",
        "BK-NORM-01",
        "官方写法（同一张表里重复填报了一次）",
    ],
    [
        "MER-ME-01",
        "CT/MRI检查记录符合率",
        "0302",
        "影像科",
        "2026-Q3",
        "970",
        "1000",
        "97",
        "%",
        "BK-NORM-02",
        "半角写法",
    ],
    [
        "MER-TQ-03",
        "",
        "0303",
        "病案室",
        "2026-Q3",
        "990",
        "1000",
        "99",
        "%",
        "BK-NORM-03",
        "指标名称为空 → 落「未归一」并计数",
    ],
    [
        "MER-TQ-03",
        "主要诊断填写正确率",
        "0303",
        "病案室",
        "2026-Q3",
        "990",
        "1000",
        "99",
        "台",
        "BK-NORM-04",
        "计量单位别名未覆盖 → 落「未归一」并计数",
    ],
]

# 科室二表：官方写法（与科室一表逐字一致 → 归确定性键那一级）+ 全角写法
SHEET_TWO = [
    [
        "MER-ME-03",
        "细菌培养检查记录符合率",
        "0301",
        "医技部",
        "2026-Q3",
        "995",
        "1000",
        "99.5",
        "%",
        "BK-NORM-01",
        "官方写法（跨表，与科室一表逐字一致）",
    ],
    [
        "MER-ME-01",
        "ＣＴ／ＭＲＩ检查记录符合率",
        "0302",
        "影像科",
        "2026-Q3",
        "970",
        "1000",
        "97",
        "%",
        "BK-NORM-02",
        "全角写法（跨表）",
    ],
]


def main() -> None:
    wb = Workbook()
    ws1 = wb.active
    ws1.title = "科室一表"
    ws1.append(HEADERS)
    for row in SHEET_ONE:
        ws1.append(row)

    ws2 = wb.create_sheet("科室二表")
    ws2.append(HEADERS)
    for row in SHEET_TWO:
        ws2.append(row)

    wb.save(OUT)
    print(f"已写出 {OUT}（2 张工作表 · {len(SHEET_ONE) + len(SHEET_TWO)} 行）")


if __name__ == "__main__":
    main()
